            "ch_in_q": {"direction": "in", "kind": "quantum", "label": "Qubit in", "max_connections": 1},
        },
        "parameters": {},
    },
}


def get_component_spec(component_type):
    return COMPONENT_MANIFEST.get(component_type)

damn_q/runner.py:
"""Experiment loader and runner executing validated DAMN-Q JSON graphs."""

import json
from pathlib import Path

import numpy as np

from Auto_connector import connect
from Classic_data_reader import Classic_data_reader
from Detector_module import Detector_module
from Emitter import Handler
from Entanglment_swapping_module import Entaglment_swapping_module
from Hardware_models import (
    DEFAULT_FIBRE_ATTENUATION_DB_PER_KM,
    combined_loss_p,
    fibre_loss_p,
    propagation_ticks,
)
from Measurer import Measuring_Device
from Measurer_memory_paired import Measurer_memory_paired
from Memory import Quantum_memory
from Orchestrator import Orchestrator
from Pauli_corrector import Pauli_corrector
from Simulation import Simulation
from Source import Source
from States import phi_plus

from damn_q.manifest import get_component_spec
from damn_q.schema import SCHEMA_VERSION, validate_experiment

SIMULATOR_VERSION = "0.2.0"


class EndpointProbe:
    """Captures arriving qubits and notifies delivery-time measurement recorders."""

    def __init__(self, id, sim):
        self.id = id
        self.sim = sim
        self.ch_in_q = Handler(self.handle_qubit, sim=self.sim, kind="quantum", max_connections=1)
        self.qubits = []
        self._listeners = []

    def add_listener(self, callback):
        self._listeners.append(callback)

    def handle_qubit(self, qubit):
        arrival_time = self.sim.time
        self.qubits.append((arrival_time, qubit))
        for cb in self._listeners:
            cb(arrival_time, qubit)


class _BellFidelityRecorder:
    """Pairs arrivals across two EndpointProbes by `pair_id` and captures fidelity at delivery."""

    def __init__(self, p1_id, p2_id, probe_a, probe_b):
        self.p1_id = p1_id
        self.p2_id = p2_id
        self._pending_a = {}
        self._pending_b = {}
        self._untagged_a = []
        self._untagged_b = []
        self.fidelities = []
        self.shared_register = []
        self.delivery_times = []
        self.latencies = []

        probe_a.add_listener(self._on_a)
        probe_b.add_listener(self._on_b)

    def _capture(self, t_a, q1, t_b, q2):
        delivery_time = max(t_a, t_b)
        same_reg = (q1.register is not None) and (q1.register is q2.register)
        if same_reg:
            joint = q1.register.reduced_density_matrix([q1, q2])
            f_val = float(np.real(np.trace(phi_plus @ joint)))
        elif q1.register is not None and q2.register is not None:
            joint = np.kron(
                q1.register.reduced_density_matrix([q1]),
                q2.register.reduced_density_matrix([q2]),
            )
            f_val = float(np.real(np.trace(phi_plus @ joint)))
        else:
            f_val = 0.0

        self.shared_register.append(same_reg)
        self.fidelities.append(f_val)
        self.delivery_times.append(delivery_time)

        c1 = getattr(q1, "created_at", None)
        c2 = getattr(q2, "created_at", None)
        if c1 is not None and c2 is not None:
            self.latencies.append(delivery_time - min(c1, c2))
        elif c1 is not None:
            self.latencies.append(delivery_time - c1)
        elif c2 is not None:
            self.latencies.append(delivery_time - c2)

    def _on_a(self, t, qubit):
        pid = getattr(qubit, "pair_id", None)
        if pid is not None:
            if pid in self._pending_b:
                t_b, q2 = self._pending_b.pop(pid)
                self._capture(t, qubit, t_b, q2)
            else:
                self._pending_a[pid] = (t, qubit)
            return
        if self._untagged_b:
            t_b, q2 = self._untagged_b.pop(0)
            self._capture(t, qubit, t_b, q2)
        else:
            self._untagged_a.append((t, qubit))

    def _on_b(self, t, qubit):
        pid = getattr(qubit, "pair_id", None)
        if pid is not None:
            if pid in self._pending_a:
                t_a, q1 = self._pending_a.pop(pid)
                self._capture(t_a, q1, t, qubit)
            else:
                self._pending_b[pid] = (t, qubit)
            return
        if self._untagged_a:
            t_a, q1 = self._untagged_a.pop(0)
            self._capture(t_a, q1, t, qubit)
        else:
            self._untagged_b.append((t, qubit))

    def to_dict(self, *, final_time=None, tick_duration_s=None):
        n_pairs = len(self.fidelities)
        out = {
            "type": "bell_fidelity",
            "probes": [self.p1_id, self.p2_id],
            "captured_at": "delivery",
            "pairs": n_pairs,
            "unmatched_a": len(self._pending_a) + len(self._untagged_a),
            "unmatched_b": len(self._pending_b) + len(self._untagged_b),
            "all_shared_register": all(self.shared_register) if self.shared_register else False,
            "fidelities": self.fidelities,
            "mean_fidelity": (sum(self.fidelities) / n_pairs) if n_pairs else None,
            "delivery_times": self.delivery_times,
            "latencies": self.latencies,
            "mean_latency": (sum(self.latencies) / len(self.latencies)) if self.latencies else None,
        }
        if tick_duration_s is not None:
            sim_s = (final_time * tick_duration_s) if final_time is not None else None
            out["delivered_pairs_per_s"] = (n_pairs / sim_s) if (sim_s and sim_s > 0) else None
            out["mean_latency_s"] = (
                out["mean_latency"] * tick_duration_s
                if out["mean_latency"] is not None
                else None
            )
        return out


def _resolve_params(ctype, raw_params):
    spec = get_component_spec(ctype)
    resolved = {}
    for name, pspec in spec["parameters"].items():
        resolved[name] = raw_params.get(name, pspec["default"])
    return resolved


def _connection_quantum_effects(conn, tick_duration_s):
    """Effective (delay, loss_p) of a quantum connection including optional fibre effects.

    Fibre length adds propagation delay (whole ticks) and attenuation/coupling loss,
    composed independently with the connection's own `loss_p`. With no fibre keys
    the connection's `delay` and `loss_p` are returned unchanged.
    """
    length_km = conn.get("length_km", 0.0)
    coupling_db = conn.get("coupling_loss_db", 0.0)
    attenuation = conn.get("attenuation_db_per_km", DEFAULT_FIBRE_ATTENUATION_DB_PER_KM)
    delay = conn.get("delay", 0) + propagation_ticks(length_km, tick_duration_s)
    extra_loss = fibre_loss_p(length_km, attenuation, coupling_db)
    loss_p = combined_loss_p(conn.get("loss_p", 0.0), extra_loss)
    return delay, loss_p


def _instantiate_component(comp_id, ctype, params, sim):
    if ctype == "source":
        return Source(
            comp_id,
            params["delay"],
            params["type"],
            sim=sim,
            initial_fidelity=params["initial_fidelity"],
        )
    if ctype == "quantum_memory":
        return Quantum_memory(
            comp_id,
            params["depolarization_p"],
            delay=params["delay"],
            capacity=params["capacity"],
            fifo=params["fifo"],
            sim=sim,
            t1=params["t1_ticks"],
            t2=params["t2_ticks"],
        )
    if ctype == "entanglement_swapper":
        return Entaglment_swapping_module(
            comp_id,
            delay=params["delay"],
            queue_capacity=params["queue_capacity"],
            queue_ttl=params["queue_ttl"],
            sim=sim,
            visibility=params["visibility"],
        )
    if ctype == "orchestrator":
        return Orchestrator(comp_id, delay=params["delay"], sim=sim)
    if ctype == "pauli_corrector":
        return Pauli_corrector(comp_id, delay=params["delay"], sim=sim)
    if ctype == "measurer":
        return Measuring_Device(
            comp_id,
            params["delay"],
            x_basis_p=params["x_basis_p"],
            p_depolarization=params["p_depolarization"],
            sim=sim,
            detector_efficiency=params["detector_efficiency"],
            dark_count_rate=params["dark_count_rate"],
        )
    if ctype == "measurer_memory_paired":
        return Measurer_memory_paired(
            comp_id,
            params["delay"],
            x_basis_p=params["x_basis_p"],
            p_depolarization=params["p_depolarization"],
            sim=sim,
            detector_efficiency=params["detector_efficiency"],
            dark_count_rate=params["dark_count_rate"],
        )
    if ctype == "classic_data_reader":
        return Classic_data_reader(
            comp_id,
            sim=sim,
            coincidence_window=params["coincidence_window"],
        )
    if ctype == "detector_module":
        return Detector_module(comp_id, trace=bool(params["trace"]), sim=sim)
    if ctype == "endpoint_probe":
        return EndpointProbe(comp_id, sim)
    raise ValueError(f"Unsupported component type: {ctype!r}")


def load_experiment(path):
    with open(Path(path), "r", encoding="utf-8") as f:
        return json.load(f)


def run_experiment(doc_or_path, *, seed_override=None, until_override=None):
    """Validate and execute a DAMN-Q experiment, returning a JSON-serializable result.

    Each call builds its own Simulation, so runs never share clock, queue,
    random stream, or process-global state. Bell fidelity probes pair arrivals
    by `pair_id` and capture joint states at delivery time.
    """
    doc = load_experiment(doc_or_path) if isinstance(doc_or_path, (str, Path)) else dict(doc_or_path)

    # Apply overrides on a shallow copy of run config before validation
    run_cfg = dict(doc.get("run", {})) if isinstance(doc.get("run"), dict) else doc.get("run")
    if isinstance(run_cfg, dict):
        if seed_override is not None:
            run_cfg["seed"] = seed_override
        if until_override is not None:
            run_cfg["until"] = until_override
        doc = dict(doc, run=run_cfg)

    # Static validation MUST run before building the simulation or components
    validate_experiment(doc)

    until = doc["run"]["until"]
    seed = doc["run"].get("seed")
    tick_duration_s = doc["run"].get("tick_duration_s")
    sim = Simulation(seed)

    instances = {}
    types = {}
    for comp in doc["components"]:
        cid = comp["id"]
        ctype = comp["type"]
        params = _resolve_params(ctype, comp.get("params", {}))
        instances[cid] = _instantiate_component(cid, ctype, params, sim)
        types[cid] = ctype

    for conn in doc.get("connections", []):
        src_obj = instances[conn["from"]["component"]]
        dst_obj = instances[conn["to"]["component"]]
        src_port = getattr(src_obj, conn["from"]["port"])
        dst_port = getattr(dst_obj, conn["to"]["port"])
        # Fibre keys are only accepted on quantum connections (schema); without them this
        # returns the connection's own delay and loss_p unchanged.
        delay, loss_p = _connection_quantum_effects(conn, tick_duration_s)
        connect(
            src_port,
            dst_port,
            delay=delay,
            loss_p=loss_p,
            depolarization_p=conn.get("depolarization_p", 0.0),
            sim=sim,
        )

    # Attach delivery-time Bell fidelity recorders before running the simulation
    recorders = []
    for m in doc.get("measurements", []):
        if m["type"] == "bell_fidelity":
            p1_id, p2_id = m["probes"]
            recorders.append(_BellFidelityRecorder(p1_id, p2_id, instances[p1_id], instances[p2_id]))

    sim.run(until)

    readers = {}
    detectors = {}
    probes = {}
    sources_metrics = {}
    memories_metrics = {}
    swappers_metrics = {}
    measurers_metrics = {}
    readers_unmatched = {}
    readers_coincidences = {}

    for cid, obj in instances.items():
        ctype = types[cid]
        if ctype == "source":
            sources_metrics[cid] = {"attempts": obj.attempts}
        elif ctype == "quantum_memory":
            memories_metrics[cid] = {
                "heralded_pairs": obj.heralded_count,
                "evicted": obj.evicted_count,
            }
        elif ctype == "entanglement_swapper":
            swappers_metrics[cid] = {
                "completed": obj.counter,
                "queued": obj.queued_count,
                "expired": obj.expired_count,
                "rejected": obj.rejected_count,
            }
        elif ctype in ("measurer", "measurer_memory_paired"):
            measurers_metrics[cid] = {
                "dark_counts": obj.dark_counts,
                "missed_detections": obj.missed_detections,
            }
        elif ctype == "classic_data_reader":
            readers[cid] = {
                "00": obj.count_00,
                "01": obj.count_01,
                "10": obj.count_10,
                "11": obj.count_11,
            }
            readers_unmatched[cid] = {
                "unmatched_1": obj.unmatched_1,
                "unmatched_2": obj.unmatched_2,
            }
            readers_coincidences[cid] = obj.coincidence_summary()
        elif ctype == "detector_module":
            detectors[cid] = {
                "total_1": obj.Total_qubits_1,
                "total_2": obj.Total_qubits_2,
                "ebits_1": obj.ebits_1,
                "ebits_2": obj.ebits_2,
                "single_1": obj.single_qubits_1,
                "single_2": obj.single_qubits_2,
            }
        elif ctype == "endpoint_probe":
            probes[cid] = {"count": len(obj.qubits)}

    measurements = [
        rec.to_dict(final_time=sim.time, tick_duration_s=tick_duration_s)
        for rec in recorders
    ]

    result = {
        "schema_version": SCHEMA_VERSION,
        "simulator_version": SIMULATOR_VERSION,
        "name": doc.get("name", ""),
        "seed": seed,
        "until": until,
        "final_time": sim.time,
        "readers": readers,
        "detectors": detectors,
        "probes": probes,
        "measurements": measurements,
        "metrics": {
            "sources": sources_metrics,
            "memories": memories_metrics,
            "swappers": swappers_metrics,
            "measurers": measurers_metrics,
            "readers_unmatched": readers_unmatched,
            "readers_coincidences": readers_coincidences,
        },
    }
    if tick_duration_s is not None:
        result["tick_duration_s"] = tick_duration_s
        result["simulated_duration_s"] = sim.time * tick_duration_s
    return result

damn_q/schema.py:
"""Validation for DAMN-Q versioned JSON experiment graphs."""

import math

from damn_q.manifest import get_component_spec
from Hardware_models import validate_storage_times

SCHEMA_VERSION = "1.0"

_FIBRE_KEYS = ("length_km", "attenuation_db_per_km", "coupling_loss_db")


class ExperimentValidationError(ValueError):
    """Raised when an experiment graph fails static validation before execution."""

    def __init__(self, errors):
        self.errors = list(errors)
        message = "Invalid DAMN-Q experiment:\n" + "\n".join(f"  - {e}" for e in self.errors)
        super().__init__(message)


def _is_number(value):
    return isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value)


def _is_integer(value):
    return isinstance(value, int) and not isinstance(value, bool)


def _validate_param(comp_id, param_name, value, spec, errors):
    ptype = spec["type"]
    if ptype == "integer":
        if not _is_integer(value):
            errors.append(f"Component {comp_id!r} parameter {param_name!r} must be an integer, got {value!r}.")
            return
    elif ptype == "number":
        if not _is_number(value):
            errors.append(f"Component {comp_id!r} parameter {param_name!r} must be a number, got {value!r}.")
            return

    if "enum" in spec and value not in spec["enum"]:
        errors.append(f"Component {comp_id!r} parameter {param_name!r} must be one of {spec['enum']}, got {value!r}.")
    if "gt" in spec and value <= spec["gt"]:
        errors.append(f"Component {comp_id!r} parameter {param_name!r} must be > {spec['gt']}, got {value!r}.")
    if "min" in spec and value < spec["min"]:
        errors.append(f"Component {comp_id!r} parameter {param_name!r} must be >= {spec['min']}, got {value!r}.")
    if "max" in spec and value > spec["max"]:
        errors.append(f"Component {comp_id!r} parameter {param_name!r} must be <= {spec['max']}, got {value!r}.")


def _resolved_params(spec, raw_params):
    resolved = {}
    for pname, pspec in spec.get("parameters", {}).items():
        resolved[pname] = raw_params.get(pname, pspec["default"])
    return resolved


def _port_is_active(port_spec, params):
    cond = port_spec.get("active_when")
    if not cond:
        return True
    return all(params.get(k) == v for k, v in cond.items())


def _classical_types_compatible(src_port_spec, dst_port_spec):
    src_mt = src_port_spec.get("message_type")
    dst_accepts = dst_port_spec.get("accepts")
    dst_mt = dst_port_spec.get("message_type")
    if src_mt is None:
        return True
    if dst_accepts is not None:
        return src_mt in dst_accepts
    if dst_mt is not None:
        return src_mt == dst_mt
    return True


def validate_experiment(doc):
    """Validate an experiment dictionary. Raises ExperimentValidationError if invalid."""
    errors = []
    if not isinstance(doc, dict):
        raise ExperimentValidationError(["Experiment document must be a JSON object."])

    version = doc.get("schema_version")
    if version != SCHEMA_VERSION:
        errors.append(f"Unsupported schema_version {version!r}; expected {SCHEMA_VERSION!r}.")

    run_cfg = doc.get("run")
    if not isinstance(run_cfg, dict):
        errors.append("Missing or invalid 'run' object.")
    else:
        until = run_cfg.get("until")
        if not _is_number(until) or until <= 0:
            errors.append(f"'run.until' must be a positive number, got {until!r}.")
        seed = run_cfg.get("seed")
        if seed is not None and not _is_integer(seed):
            errors.append(f"'run.seed' must be an integer or null, got {seed!r}.")
        tick_s = run_cfg.get("tick_duration_s")
        if tick_s is not None and (not _is_number(tick_s) or tick_s <= 0):
            errors.append(f"'run.tick_duration_s' must be a positive number or null, got {tick_s!r}.")

    components = doc.get("components")
    comp_map = {}
    if not isinstance(components, list) or not components:
        errors.append("'components' must be a non-empty list.")
    else:
        for idx, comp in enumerate(components):
            if not isinstance(comp, dict):
                errors.append(f"components[{idx}] must be an object.")
                continue
            cid = comp.get("id")
            ctype = comp.get("type")
            if not isinstance(cid, str) or not cid.strip():
                errors.append(f"components[{idx}].id must be a non-empty string.")
                continue
            if cid in comp_map:
                errors.append(f"Duplicate component id {cid!r}.")
                continue
            if not isinstance(ctype, str):
                errors.append(f"Component {cid!r} type must be a string, got {ctype!r}.")
                continue
            spec = get_component_spec(ctype)
            if spec is None:
                errors.append(f"Component {cid!r} has unknown type {ctype!r}.")
                continue

            params = comp.get("params", {})
            if not isinstance(params, dict):
                errors.append(f"Component {cid!r} 'params' must be an object.")
                comp_map[cid] = (ctype, spec, _resolved_params(spec, {}))
                continue
            for pname, pval in params.items():
                if pname not in spec["parameters"]:
                    errors.append(f"Component {cid!r} ({ctype}) has unknown parameter {pname!r}.")
                else:
                    _validate_param(cid, pname, pval, spec["parameters"][pname], errors)
            resolved = _resolved_params(spec, params)
            comp_map[cid] = (ctype, spec, resolved)
            if ctype == "quantum_memory":
                t1, t2 = resolved.get("t1_ticks"), resolved.get("t2_ticks")
                if _is_number(t1) and _is_number(t2) and t1 >= 0 and t2 >= 0:
                    try:
                        validate_storage_times(t1, t2)
                    except ValueError as exc:
                        errors.append(f"Component {cid!r} (quantum_memory): {exc}")

    connections = doc.get("connections", [])
    run_tick_s = run_cfg.get("tick_duration_s") if isinstance(run_cfg, dict) else None
    seen_edges = set()
    out_counts = {}
    in_counts = {}
    if not isinstance(connections, list):
        errors.append("'connections' must be a list.")
    else:
        for idx, conn in enumerate(connections):
            if not isinstance(conn, dict):
                errors.append(f"connections[{idx}] must be an object.")
                continue
            src = conn.get("from")
            dst = conn.get("to")
            if not isinstance(src, dict) or not isinstance(dst, dict):
                errors.append(f"connections[{idx}] must have 'from' and 'to' objects.")
                continue

            src_cid, src_port = src.get("component"), src.get("port")
            dst_cid, dst_port = dst.get("component"), dst.get("port")
            if not isinstance(src_cid, str) or not isinstance(src_port, str):
                errors.append(f"connections[{idx}].from component and port must be strings.")
                continue
            if not isinstance(dst_cid, str) or not isinstance(dst_port, str):
                errors.append(f"connections[{idx}].to component and port must be strings.")
                continue
            src_info = comp_map.get(src_cid)
            dst_info = comp_map.get(dst_cid)

            if src_info is None:
                errors.append(f"connections[{idx}].from references unknown component {src_cid!r}.")
                continue
            if dst_info is None:
                errors.append(f"connections[{idx}].to references unknown component {dst_cid!r}.")
                continue

            src_port_spec = src_info[1]["ports"].get(src_port)
            dst_port_spec = dst_info[1]["ports"].get(dst_port)
            if src_port_spec is None:
                errors.append(f"connections[{idx}].from references unknown port {src_port!r} on {src_cid!r}.")
                continue
            if dst_port_spec is None:
                errors.append(f"connections[{idx}].to references unknown port {dst_port!r} on {dst_cid!r}.")
                continue

            if src_port_spec["direction"] != "out":
                errors.append(f"connections[{idx}].from port {src_cid}.{src_port} is not an output port.")
            if dst_port_spec["direction"] != "in":
                errors.append(f"connections[{idx}].to port {dst_cid}.{dst_port} is not an input port.")

            if not _port_is_active(src_port_spec, src_info[2]):
                errors.append(
                    f"connections[{idx}].from port {src_cid}.{src_port} is inactive under the component's current parameters."
                )
            if not _port_is_active(dst_port_spec, dst_info[2]):
                errors.append(
                    f"connections[{idx}].to port {dst_cid}.{dst_port} is inactive under the component's current parameters."
                )

            edge_key = (src_cid, src_port, dst_cid, dst_port)
            if edge_key in seen_edges:
                errors.append(
                    f"connections[{idx}] duplicates existing connection "
                    f"{src_cid}.{src_port} -> {dst_cid}.{dst_port}."
                )
            else:
                seen_edges.add(edge_key)

            if src_port_spec["kind"] != dst_port_spec["kind"]:
                errors.append(
                    f"connections[{idx}] connects incompatible port types: "
                    f"{src_cid}.{src_port} ({src_port_spec['kind']}) -> "
                    f"{dst_cid}.{dst_port} ({dst_port_spec['kind']})."
                )
            else:
                if src_port_spec["kind"] == "classical" and not _classical_types_compatible(
                    src_port_spec, dst_port_spec
                ):
                    src_mt = src_port_spec.get("message_type")
                    dst_mt = dst_port_spec.get("accepts") or dst_port_spec.get("message_type")
                    errors.append(
                        f"connections[{idx}] connects incompatible classical message types: "
                        f"{src_cid}.{src_port} ({src_mt}) -> {dst_cid}.{dst_port} (expects {dst_mt})."
                    )

                # Output fan-out limit
                out_key = (src_cid, src_port)
                out_counts[out_key] = out_counts.get(out_key, 0) + 1
                out_max = src_port_spec.get("max_connections")
                if out_max is not None and out_counts[out_key] > out_max:
                    if src_port_spec["kind"] == "quantum":
                        errors.append(
                            f"connections[{idx}] fans out quantum output port {src_cid}.{src_port}; "
                            f"a quantum connection must transfer ownership to a single destination."
                        )
                    else:
                        errors.append(
                            f"connections[{idx}] fans out classical output port {src_cid}.{src_port} "
                            f"beyond max_connections={out_max}."
                        )

                # Input fan-in limit
                in_key = (dst_cid, dst_port)
                in_counts[in_key] = in_counts.get(in_key, 0) + 1
                in_max = dst_port_spec.get("max_connections")
                if in_max is not None and in_counts[in_key] > in_max:
                    errors.append(
                        f"connections[{idx}] fans in to {dst_port_spec['kind']} input port "
                        f"{dst_cid}.{dst_port} beyond max_connections={in_max}."
                    )

            delay = conn.get("delay", 0)
            loss_p = conn.get("loss_p", 0.0)
            depol_p = conn.get("depolarization_p", 0.0)
            if not _is_number(delay) or delay < 0:
                errors.append(f"connections[{idx}].delay must be >= 0, got {delay!r}.")
            if not _is_number(loss_p) or not (0.0 <= loss_p <= 1.0):
                errors.append(f"connections[{idx}].loss_p must be in [0, 1], got {loss_p!r}.")
            if not _is_number(depol_p) or not (0.0 <= depol_p <= 1.0):
                errors.append(f"connections[{idx}].depolarization_p must be in [0, 1], got {depol_p!r}.")
            if src_port_spec["kind"] == "classical" and (loss_p != 0.0 or depol_p != 0.0):
                errors.append(
                    f"connections[{idx}] is classical and cannot set quantum loss_p or depolarization_p."
                )

            fibre_present = [k for k in _FIBRE_KEYS if k in conn]
            if fibre_present and src_port_spec["kind"] == "classical":
                errors.append(
                    f"connections[{idx}] is classical and cannot set fibre parameters {fibre_present}."
                )
            for key in fibre_present:
                value = conn[key]
                if not _is_number(value) or value < 0:
                    errors.append(f"connections[{idx}].{key} must be a non-negative number, got {value!r}.")
            length_km = conn.get("length_km", 0.0)
            if _is_number(length_km) and length_km > 0 and run_tick_s is None:
                errors.append(
                    f"connections[{idx}] sets length_km and requires 'run.tick_duration_s' to convert fibre "
                    f"propagation delay to ticks."
                )

    measurements = doc.get("measurements", [])
    if not isinstance(measurements, list):
        errors.append("'measurements' must be a list.")
    else:
        for idx, m in enumerate(measurements):
            if not isinstance(m, dict):
                errors.append(f"measurements[{idx}] must be an object.")
                continue
            mtype = m.get("type")
            if mtype == "bell_fidelity":
                probes = m.get("probes")
                if not isinstance(probes, list) or len(probes) != 2:
                    errors.append(f"measurements[{idx}].probes must be a 2-element list of endpoint_probe IDs.")
                elif not all(isinstance(pid, str) for pid in probes):
                    errors.append(f"measurements[{idx}].probes entries must be strings.")
                elif probes[0] == probes[1]:
                    errors.append(f"measurements[{idx}].probes must reference two distinct endpoint probes.")
                else:
                    for pid in probes:
                        info = comp_map.get(pid)
                        if info is None or info[0] != "endpoint_probe":
                            errors.append(
                                f"measurements[{idx}] references {pid!r}, which is not an endpoint_probe."
                            )
            else:
                errors.append(f"measurements[{idx}] has unknown type {mtype!r}.")

    # Discrete per-tick memory depolarization (depolarization_p > 0) requires integer
    # storage ticks at runtime; reject fractional delays statically when it is enabled.
    discrete_depol_memories = [
        cid
        for cid, (ctype, _spec, resolved) in comp_map.items()
        if ctype == "quantum_memory"
        and _is_number(resolved.get("depolarization_p"))
        and resolved["depolarization_p"] > 0.0
    ]
    if discrete_depol_memories:
        mem_list = ", ".join(repr(cid) for cid in discrete_depol_memories)
        for cid, (_ctype, _spec, resolved) in comp_map.items():
            d = resolved.get("delay")
            if _is_number(d) and not float(d).is_integer():
                errors.append(
                    f"Component {cid!r} parameter 'delay' must be an integer tick count (got {d!r}) "
                    f"because quantum memory {mem_list} uses discrete per-tick depolarization_p > 0."
                )
        if isinstance(connections, list):
            for idx, conn in enumerate(connections):
                if not isinstance(conn, dict):
                    continue
                d = conn.get("delay", 0)
                if _is_number(d) and not float(d).is_integer():
                    errors.append(
                        f"connections[{idx}].delay must be an integer tick count (got {d!r}) "
                        f"because quantum memory {mem_list} uses discrete per-tick depolarization_p > 0."
                    )

    if errors:
        raise ExperimentValidationError(errors)

damn_q/server.py:
"""Local HTTP server for the DAMN-Q browser workbench.

Serves the static web UI and exposes JSON endpoints backed directly by
`damn_q.manifest`, `damn_q.schema.validate_experiment`, and
`damn_q.runner.run_experiment` — the exact same path used by the CLI.
"""

import json
import mimetypes
import urllib.parse
import webbrowser
from http import HTTPStatus
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path

from damn_q.manifest import CHANNEL_MANIFEST, COMPONENT_MANIFEST, MANIFEST_VERSION
from damn_q.runner import SIMULATOR_VERSION, load_experiment, run_experiment
from damn_q.schema import ExperimentValidationError, SCHEMA_VERSION, validate_experiment

WEB_DIR = Path(__file__).resolve().parent / "web"
DEFAULT_EXPERIMENTS_DIR = Path(__file__).resolve().parent.parent / "experiments"
MAX_BODY_BYTES = 5 * 1024 * 1024


def _json_bytes(payload):
    return json.dumps(payload, indent=2).encode("utf-8")


def _list_examples(experiments_dir):
    if not experiments_dir.is_dir():
        return []
    items = []
    for path in sorted(experiments_dir.glob("*.json")):
        try:
            doc = load_experiment(path)
        except (OSError, json.JSONDecodeError):
            continue
        items.append(
            {
                "filename": path.name,
                "name": doc.get("name", path.stem),
                "description": doc.get("description", ""),
            }
        )
    return items


def _make_handler(web_dir, experiments_dir):
    web_root = web_dir.resolve()
    exp_root = experiments_dir.resolve()

    class WorkbenchHandler(BaseHTTPRequestHandler):
        def log_message(self, format, *args):
            # Keep server stdout/stderr clean during tests and CLI usage
            return

        def _send_bytes(self, status, body, content_type):
            self.send_response(status)
            self.send_header("Content-Type", content_type)
            self.send_header("Content-Length", str(len(body)))
            self.send_header("Cache-Control", "no-store")
            self.end_headers()
            self.wfile.write(body)

        def _send_json(self, status, payload):
            self._send_bytes(status, _json_bytes(payload), "application/json; charset=utf-8")

        def _read_json_body(self):
            raw_len = self.headers.get("Content-Length", "0")
            try:
                length = int(raw_len)
            except ValueError:
                return None, "Invalid Content-Length header."
            if length < 0 or length > MAX_BODY_BYTES:
                return None, f"Request body size out of range (max {MAX_BODY_BYTES} bytes)."
            raw = self.rfile.read(length)
            try:
                return json.loads(raw.decode("utf-8")), None
            except (UnicodeDecodeError, json.JSONDecodeError) as exc:
                return None, f"Invalid JSON payload: {exc}"

        def _serve_file(self, rel_path):
            candidate = (web_root / rel_path).resolve()
            if web_root not in candidate.parents and candidate != web_root:
                self._send_json(HTTPStatus.FORBIDDEN, {"ok": False, "error": "Forbidden path."})
                return
            if not candidate.is_file():
                self._send_json(HTTPStatus.NOT_FOUND, {"ok": False, "error": "File not found."})
                return
            ctype, _ = mimetypes.guess_type(str(candidate))
            if ctype is None:
                ctype = "application/octet-stream"
            if ctype.startswith("text/") or ctype in ("application/javascript", "application/json"):
                ctype = f"{ctype}; charset=utf-8"
            self._send_bytes(HTTPStatus.OK, candidate.read_bytes(), ctype)

        def do_GET(self):
            parsed = urllib.parse.urlsplit(self.path)
            path = parsed.path

            if path == "/" or path == "/index.html":
                self._serve_file("index.html")
                return

            if path.startswith("/static/"):
                rel = urllib.parse.unquote(path[len("/static/"):])
                self._serve_file(rel)
                return

            if path == "/api/manifest":
                self._send_json(
                    HTTPStatus.OK,
                    {
                        "schema_version": SCHEMA_VERSION,
                        "manifest_version": MANIFEST_VERSION,
                        "simulator_version": SIMULATOR_VERSION,
                        "channels": CHANNEL_MANIFEST,
                        "components": COMPONENT_MANIFEST,
                    },
                )
                return

            if path == "/api/examples":
                self._send_json(HTTPStatus.OK, {"examples": _list_examples(exp_root)})
                return

            if path.startswith("/api/examples/"):
                filename = urllib.parse.unquote(path[len("/api/examples/"):])
                if "/" in filename or "\\" in filename or not filename.endswith(".json"):
                    self._send_json(HTTPStatus.BAD_REQUEST, {"ok": False, "error": "Invalid example filename."})
                    return
                candidate = (exp_root / filename).resolve()
                if exp_root not in candidate.parents or not candidate.is_file():
                    self._send_json(HTTPStatus.NOT_FOUND, {"ok": False, "error": f"Example {filename!r} not found."})
                    return
                try:
                    doc = load_experiment(candidate)
                except (OSError, json.JSONDecodeError) as exc:
                    self._send_json(HTTPStatus.INTERNAL_SERVER_ERROR, {"ok": False, "error": str(exc)})
                    return
                self._send_json(HTTPStatus.OK, doc)
                return

            self._send_json(HTTPStatus.NOT_FOUND, {"ok": False, "error": f"Unknown route: {path}"})

        def do_POST(self):
            parsed = urllib.parse.urlsplit(self.path)
            path = parsed.path

            if path == "/api/validate":
                doc, err = self._read_json_body()
                if err is not None:
                    self._send_json(HTTPStatus.BAD_REQUEST, {"ok": False, "errors": [err], "error": err})
                    return
                try:
                    validate_experiment(doc)
                except ExperimentValidationError as exc:
                    self._send_json(
                        HTTPStatus.BAD_REQUEST,
                        {"ok": False, "errors": exc.errors, "error": str(exc)},
                    )
                    return
                self._send_json(HTTPStatus.OK, {"ok": True, "schema_version": SCHEMA_VERSION})
                return

            if path == "/api/run":
                doc, err = self._read_json_body()
                if err is not None:
                    self._send_json(HTTPStatus.BAD_REQUEST, {"ok": False, "errors": [err], "error": err})
                    return
                try:
                    result = run_experiment(doc)
                except ExperimentValidationError as exc:
                    self._send_json(
                        HTTPStatus.BAD_REQUEST,
                        {"ok": False, "errors": exc.errors, "error": str(exc)},
                    )
                    return
                except ValueError as exc:
                    self._send_json(
                        HTTPStatus.BAD_REQUEST,
                        {"ok": False, "errors": [str(exc)], "error": str(exc)},
                    )
                    return
                self._send_json(HTTPStatus.OK, {"ok": True, "result": result})
                return

            self._send_json(HTTPStatus.NOT_FOUND, {"ok": False, "error": f"Unknown route: {path}"})

    return WorkbenchHandler


def create_server(host="127.0.0.1", port=8000, *, web_dir=None, experiments_dir=None):
    """Create a configured ThreadingHTTPServer for the DAMN-Q workbench."""
    handler_cls = _make_handler(
        Path(web_dir) if web_dir is not None else WEB_DIR,
        Path(experiments_dir) if experiments_dir is not None else DEFAULT_EXPERIMENTS_DIR,
    )
    return ThreadingHTTPServer((host, port), handler_cls)


def serve_workbench(host="127.0.0.1", port=8000, *, open_browser=True):
    """Start the DAMN-Q browser workbench and block until interrupted."""
    server = create_server(host=host, port=port)
    actual_host, actual_port = server.server_address
    url = f"http://{actual_host}:{actual_port}/"
    print(f"DAMN-Q Workbench running at {url} (Press Ctrl+C to stop)")
    if open_browser:
        webbrowser.open(url)
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        print("\nStopping DAMN-Q Workbench.")
    finally:
        server.server_close()

damn_q/stats.py:
"""O(1)-memory streaming statistics with optional full sample tracing."""

import math


class StreamingStats:
    """Online Welford mean/std/min/max accumulator; keeps samples only if `trace=True`."""

    def __init__(self, *, trace=False):
        self.trace = bool(trace)
        self.count = 0
        self._mean = 0.0
        self._m2 = 0.0
        self.min_val = None
        self.max_val = None
        self.samples = []

    def add(self, value):
        x = float(value)
        self.count += 1
        delta = x - self._mean
        self._mean += delta / self.count
        delta2 = x - self._mean
        self._m2 += delta * delta2
        if self.min_val is None or x < self.min_val:
            self.min_val = x
        if self.max_val is None or x > self.max_val:
            self.max_val = x
        if self.trace:
            self.samples.append(x)

    @property
    def mean(self):
        return self._mean if self.count > 0 else None

    @property
    def std(self):
        if self.count == 0:
            return None
        return math.sqrt(max(0.0, self._m2 / self.count))

    def to_dict(self):
        if self.count == 0:
            return None
        out = {
            "count": self.count,
            "mean": self.mean,
            "std": self.std,
            "min": self.min_val,
            "max": self.max_val,
        }
        if self.trace:
            out["samples"] = list(self.samples)
        return out
